ed.'=>'✓ Todos os modelos criados.','✓ All translated.'=>'✓ Todas as traduções concluídas.','✓ Configured'=>'✓ Configurado','✓ Connection OK'=>'✓ Conexão OK','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Conteúdo gerado — veja a sobreposição para revisar, refinar e aplicar.','✓ Done'=>'✓ Concluído','✓ Enabled'=>'✓ Ativado','✓ Good length'=>'✓ Bom comprimento','✓ Hreflang active'=>'✓ Hreflang ativo','✓ In safe storage'=>'✓ Em armazenamento seguro','✓ Language installed.'=>'✓ Língua instalada.','✓ LF outputs'=>'✓ Saídas LF','✓ LF outputs Article / WebPage / WebSite'=>'✓ Saídas LF Artigo / Página Web / Website','✓ LF outputs full OG + Twitter Cards'=>'✓ Saídas LF OG completo + Cartões Twitter','✓ LF outputs — plugin hreflang suppressed'=>'✓ Saídas LF — hreflang do plugin suprimido','✓ Links fixed.'=>'✓ Links corrigidos.','✓ Nav refs fixed.'=>'✓ Referências de navegação corrigidas.','✓ Parts fixed.'=>'✓ Partes corrigidas.','✓ Pattern translated.'=>'✓ Padrão traduzido.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ robots.txt físico encontrado. A diretiva Sitemap do LF está presente.','✓ Refined — review the updated draft above.'=>'✓ Refinado — reveja o rascunho atualizado acima.','✓ Translation saved'=>'✓ Tradução salva','✓ WP core canonical removed'=>'✓ Canonical do núcleo WP removido','✗ %s ping failed. The sitemap URL is still announced in robots.txt — the search engine will discover it on its next crawl.'=>'✗ %s falhou no ping. A URL do sitemap ainda é anunciada no robots.txt — o motor de busca irá descobri-la na sua próxima varredura.','✗ Disabled'=>'✗ Desativado','✗ Error:'=>'✗ Erro:','✗ Failed:'=>'✗ Falhou:','✗ Not configured'=>'✗ Não configurado','✗ Too long'=>'✗ Muito longo','✗ Too short'=>'✗ Muito curto','❌ Failed'=>'❌ Falhou','📄 Wrong template'=>'📄 Modelo incorreto','📍 Stale path (page moved)'=>'📍 Caminho obsoleto (página movida)']];
